exs.code:
.ikon {
  width: var(--icon-size-md);
  height: var(--icon-size-md);
  stroke: currentColor;            /* warna ikut teks */
  stroke-width: var(--icon-stroke);
  fill: none;
}
.ikon--kecil { width: var(--icon-size-sm); height: var(--icon-size-sm); }

.panel {
  transform: translateX(100%);
  transition: transform var(--motion-duration-base) var(--motion-easing-standard);
}
.panel[data-terbuka="true"] { transform: translateX(0); }

.tombol:hover {
  transition: background-color var(--motion-duration-fast) var(--motion-easing-standard);
}
/* saat prefers-reduced-motion aktif, token durasi sudah 0ms: tidak perlu aturan baru */

{
  "space": {
    "4":  { "$type": "dimension", "$value": "16px" },
    "6":  { "$type": "dimension", "$value": "24px" },
    "inset": {
      "md": { "$value": "{space.4}" },
      "lg": { "$value": "{space.6}" }
    }
  },
  "card": {
    "padding": { "$value": "{space.inset.lg}" }
  }
}

{
  "teal": {
    "700": { "$type": "color", "$value": "#166534",
             "$description": "Tema Celengan Syariah: hanya primitif ini yang berbeda" }
  }
}

.kartu-tabungan {
  padding: var(--space-300);              /* 24px */
  display: grid;
  gap: var(--space-100);                  /* 8px antarbaris */
}
.kartu-tabungan h3 { font-size: var(--font-size-400); margin: 0; }
.kartu-tabungan .nominal { font-size: var(--font-size-500); }
.kartu-tabungan .keterangan { font-size: var(--font-size-100); }

:root {
  /* 16 x 1,2^n, dibulatkan */
  --font-size-100: .833rem;  /* 13.3px */
  --font-size-200: 1rem;     /* 16px   */
  --font-size-300: 1.2rem;   /* 19.2px */
  --font-size-400: 1.44rem;  /* 23px   */
  --font-size-500: 1.728rem; /* 27.6px */
}

{
  "radius": {
    "md": { "$type": "dimension", "$value": "12px" }
  },
  "duration": {
    "fast": { "$type": "duration", "$value": "150ms",
              "$description": "Hover dan fokus" }
  }
}

/* hasil build untuk web */
:root {
  --radius-md: 12px;
  --duration-fast: 150ms;
}

{
  "color": {
    "teal":   { "700": { "$type": "color", "$value": "#0F766E" } },
    "brand":  { "primary": { "$type": "color", "$value": "{color.teal.700}" } },
    "action": { "primary": { "$type": "color", "$value": "{color.brand.primary}" } }
  }
}

/* hasil build: rantai alias tetap terlihat */
:root {
  --color-teal-700: #0F766E;
  --color-brand-primary: var(--color-teal-700);
  --color-action-primary: var(--color-brand-primary);
}
